import React, { useState, useEffect, useRef } from 'react';
import Blobs from '../components/Blobs';

const PHASES = [
  { name:'Andas in',  seconds:4, scale:1.45, color:'rgba(120,100,220,0.25)' },
  { name:'Håll',      seconds:7, scale:1.45, color:'rgba(200,160,60,0.2)' },
  { name:'Andas ut',  seconds:8, scale:1.0,  color:'rgba(60,180,120,0.18)' },
];
const TOTAL_CYCLES = 4;

export default function Breathing({ setPage }) {
  const [running,  setRunning]  = useState(false);
  const [done,     setDone]     = useState(false);
  const [phase,    setPhase]    = useState(0);
  const [count,    setCount]    = useState(0);
  const [cycle,    setCycle]    = useState(0);
  const [scale,    setScale]    = useState(1);
  const [glow,     setGlow]     = useState(PHASES[0].color);
  const timer = useRef(null);

  const runPhase = (phaseIdx, cycleIdx) => {
    if (cycleIdx >= TOTAL_CYCLES) { setRunning(false); setDone(true); return; }
    const p = PHASES[phaseIdx];
    setPhase(phaseIdx);
    setCycle(cycleIdx);
    setCount(p.seconds);
    setScale(p.scale);
    setGlow(p.color);

    let c = p.seconds;
    timer.current = setInterval(() => {
      c--;
      setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const nextPhase = (phaseIdx + 1) % PHASES.length;
        const nextCycle = nextPhase === 0 ? cycleIdx + 1 : cycleIdx;
        setTimeout(() => runPhase(nextPhase, nextCycle), 300);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);

  if (done) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="blue" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ fontSize:64, marginBottom:24 }}>🌿</div>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:16 }}>Bra jobbat</h2>
        <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={() => setPage('checkin')} style={{ padding:'12px 24px', borderRadius:100, background:'#fff', color:'#0e0e12', fontSize:13, fontWeight:600 }}>Checka in humöret</button>
          <button onClick={() => { setDone(false); setRunning(false); }} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(255,255,255,0.7)', fontSize:13 }}>Gör om</button>
        </div>
      </div>
    </div>
  );

  const currentPhase = PHASES[phase];

  return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="blue" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'80px 24px 48px', maxWidth:400, width:'100%', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:16 }}>
          Andningsövning
        </p>
        <h1 style={{ fontSize:'clamp(24px,5vw,36px)', fontWeight:700, letterSpacing:'-0.03em', color:'#fff', marginBottom:8 }}>
          4 – 7 – 8
        </h1>
        <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', marginBottom:48, fontWeight:300 }}>
          Aktiverar det parasympatiska nervsystemet.
        </p>

        {/* Technique steps */}
        {!running && (
          <div style={{ display:'flex', gap:28, justifyContent:'center', marginBottom:52 }}>
            {PHASES.map((p, i) => (
              <div key={i} style={{ textAlign:'center' }}>
                <div style={{ fontSize:28, fontWeight:700, color:'#fff', lineHeight:1, marginBottom:4 }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.3)', letterSpacing:'0.12em', textTransform:'uppercase' }}>{p.name}</div>
              </div>
            ))}
          </div>
        )}

        {/* Animated circle */}
        <div style={{ position:'relative', width:200, height:200, margin:'0 auto 48px' }}>
          {/* Outer glow */}
          <div style={{ position:'absolute', inset:-20, borderRadius:'50%', background:running ? glow : 'rgba(100,80,180,0.15)', filter:'blur(20px)', transition:'all 1s ease', animation: running ? 'none' : 'pulse 3s ease-in-out infinite' }} />
          {/* Ring */}
          <div style={{ position:'absolute', inset:0, borderRadius:'50%', border:'1px solid rgba(255,255,255,0.08)' }} />
          {/* Animated ring */}
          <div style={{ position:'absolute', inset:0, borderRadius:'50%', border:'1px solid rgba(255,255,255,0.2)', transform:`scale(${running ? scale : 1})`, transition: running ? `transform ${currentPhase.seconds * 0.9}s linear` : 'transform .5s ease' }} />
          {/* Inner */}
          <div style={{ position:'absolute', inset:20, borderRadius:'50%', background: running ? glow : 'rgba(100,80,180,0.1)', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', transition:'background 1s ease' }}>
            {running ? (
              <>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(255,255,255,0.5)', marginBottom:4 }}>{currentPhase.name}</div>
                <div style={{ fontSize:44, fontWeight:700, color:'#fff', lineHeight:1 }}>{count}</div>
              </>
            ) : (
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:11, color:'rgba(255,255,255,0.35)', letterSpacing:'0.1em' }}>Redo</div>
            )}
          </div>
        </div>

        {running && (
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:11, color:'rgba(255,255,255,0.3)', marginBottom:36 }}>
            Omgång {cycle + 1} av {TOTAL_CYCLES}
          </p>
        )}

        {!running && (
          <button onClick={start}
            style={{ padding:'16px 48px', borderRadius:100, background:'#fff', color:'#0e0e12', fontSize:14, fontWeight:600, transition:'opacity .2s' }}
            onMouseEnter={e=>e.currentTarget.style.opacity='.85'} onMouseLeave={e=>e.currentTarget.style.opacity='1'}>
            Starta
          </button>
        )}
      </div>
    </div>
  );
}
